import sys

def main():
    data = sys.stdin.read().split()
    m = int(data[0])
    own = {}
    parent = {}
    children = {}
    jobs = set()
    for i in range(m):
        p = data[1 + 3 * i]
        c = data[2 + 3 * i]
        r = int(data[3 + 3 * i])
        jobs.add(p)
        if c == 'NULL':
            own[p] = r
        else:
            jobs.add(c)
            parent[c] = p
            own[c] = r
            children.setdefault(p, []).append(c)
    out = []
    for root in sorted(j for j in jobs if j not in parent):
        order = [root]
        for v in order:
            order.extend(children.get(v, ()))
        out.append(root + ' ' + str(sum(own.get(v, 0) for v in order)))
    print('\n'.join(out))

